import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom'
import { useNavigate } from 'react-router-dom';
import { useAuth } from '../../context/AuthContext';
import Button from '../../components/common/Button/Button';
import Input from '../../components/common/Input/Input';
import PasswordInput from '../../components/common/PasswordInput/PasswordInput';
import styles from './LoginPage.module.css';

const LoginPage = () => {
    console.log('[LoginPage] Component rendered');
    const navigate = useNavigate();
    const { login } = useAuth();
    const [email, setEmail] = useState('');
    const [password, setPassword] = useState('');
    const [error, setError] = useState('');
    const [loading, setLoading] = useState(false);

    const theme = localStorage.getItem('theme') || 'light';
    const logoSrc = theme === 'dark' ? '/assets/images/logo.png' : '/assets/images/logo_t.png';

    // Логируем изменения состояния
    useEffect(() => {
        console.log('[LoginPage] error state changed to:', error);
    }, [error]);

    useEffect(() => {
        console.log('[LoginPage] loading state changed to:', loading);
    }, [loading]);

    const handleSubmit = async (e) => {
        console.log('[LoginPage] handleSubmit STARTED');
        console.log('[LoginPage] Event object:', e);
        console.log('[LoginPage] Email:', email);
        console.log('[LoginPage] Password length:', password.length);

        e.preventDefault();
        console.log('[LoginPage] e.preventDefault() called');

        e.stopPropagation();
        console.log('[LoginPage] e.stopPropagation() called');

        console.log('[LoginPage] Setting loading to true');
        setLoading(true);

        console.log('[LoginPage] Clearing error');
        setError('');

        try {
            console.log('[LoginPage] Calling login function...');
            const loginResult = await login(email, password);
            console.log('[LoginPage] Login successful, result:', loginResult);
            console.log('[LoginPage] Navigating to /');
            navigate('/');
            console.log('[LoginPage] Navigate called');
        } catch (err) {
            console.log('[LoginPage] === ERROR CAUGHT ===');
            console.log('[LoginPage] Error object:', err);
            console.log('[LoginPage] Error type:', typeof err);
            console.log('[LoginPage] Error constructor:', err.constructor.name);
            console.log('[LoginPage] Error message:', err.message);
            console.log('[LoginPage] Error stack:', err.stack);

            let errorMessage = 'Неверный email или пароль';
            if (err.message) {
                errorMessage = err.message;
            }

            console.log('[LoginPage] Setting error message to:', errorMessage);
            setError(errorMessage);
            console.log('[LoginPage] Error state updated');

            // Отслеживаем перезагрузку
            console.log('[LoginPage] Scheduling reload check...');
            setTimeout(() => {
                console.log('[LoginPage] CHECK: Page still alive after 100ms');
            }, 100);
            setTimeout(() => {
                console.log('[LoginPage] CHECK: Page still alive after 500ms');
            }, 500);
            setTimeout(() => {
                console.log('[LoginPage] CHECK: Page still alive after 1000ms');
            }, 1000);
            setTimeout(() => {
                console.log('[LoginPage] CHECK: Page still alive after 2000ms');
            }, 2000);
        } finally {
            console.log('[LoginPage] Finally block - setting loading to false');
            setLoading(false);
            console.log('[LoginPage] handleSubmit FINISHED');
        }
    };

    return (
        <div className={styles.loginPage}>
            <div className={styles.container}>
                <div className={styles.loginCard}>
                    <div className={styles.header}>
                        <img src={logoSrc} alt="Volley Hub" className={styles.logo} />
                        <h1 className={styles.title}>Вход в аккаунт</h1>
                        <p className={styles.subtitle}>Добро пожаловать обратно!</p>
                    </div>

                    <form onSubmit={handleSubmit} className={styles.form}>
                        {error && <div className={styles.errorMessage}>Ошибка: {error}</div>}

                        <Input
                            label="Email"
                            type="email"
                            placeholder="Введите ваш email"
                            value={email}
                            onChange={(e) => {
                                console.log('[LoginPage] Email changed:', e.target.value);
                                setEmail(e.target.value);
                            }}
                            required
                        />

                        <PasswordInput
                            label="Пароль"
                            placeholder="Введите пароль"
                            value={password}
                            onChange={(e) => {
                                console.log('[LoginPage] Password changed, length:', e.target.value.length);
                                setPassword(e.target.value);
                            }}
                            required
                        />

                        <Button
                            type="submit"
                            fullWidth
                            size="large"
                            loading={loading}
                            onClick={() => console.log('[LoginPage] Button clicked')}
                        >
                            Войти
                        </Button>
                    </form>

                    <div className={styles.footer}>
                        <p className={styles.registerLink}>
                            Нет аккаунта? <Link to="/register">Зарегистрироваться</Link>
                        </p>
                    </div>
                </div>
            </div>
        </div>
    );
};

export default LoginPage;
